package net.civeira.phylax.features.access.oauthclient.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.access.tenant.domain.TenantReference;

class OauthClientFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_oauth_client_filter_builder() {
    OauthClientFilter filter = OauthClientFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getWithBackchannelLogoutUrl().isPresent(),
        "WithBackchannelLogoutUrl must be empty if filter is build without it");
    filter.setWithBackchannelLogoutUrl(true);
    Assertions.assertEquals(true, filter.getWithBackchannelLogoutUrl().get(),
        "WithBackchannelLogoutUrl must be the same as the assigned");
    Assertions.assertFalse(filter.getWithFrontchannelLogoutUrl().isPresent(),
        "WithFrontchannelLogoutUrl must be empty if filter is build without it");
    filter.setWithFrontchannelLogoutUrl(true);
    Assertions.assertEquals(true, filter.getWithFrontchannelLogoutUrl().get(),
        "WithFrontchannelLogoutUrl must be the same as the assigned");
    Assertions.assertFalse(filter.getCode().isPresent(),
        "Code must be empty if filter is build without it");
    filter.setCode("one");
    Assertions.assertEquals("one", filter.getCode().get(), "Code must be the same as the assigned");
    Assertions.assertFalse(filter.getTenant().isPresent(),
        "Tenant must be empty if filter is build without it");
    filter.setTenant(TenantReference.of("$ref"));
    Assertions.assertEquals(TenantReference.of("$ref"), filter.getTenant().get(),
        "Tenant must be the same as the assigned");
    Assertions.assertTrue(filter.getTenants().isEmpty(),
        "Tenants must be empty if filter is build without it");
    filter.setTenants(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getTenants(),
        "Tenants must be the same as the assigned");
    Assertions.assertFalse(filter.getTenantAccessible().isPresent(),
        "TenantAccessible must be empty if filter is build without it");
    filter.setTenantAccessible("one");
    Assertions.assertEquals("one", filter.getTenantAccessible().get(),
        "TenantAccessible must be the same as the assigned");
  }

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test the filter of a unique index")
  void test_oauth_client_filter_by_tenant_and_code() {
    OauthClientFilter filter = OauthClientFilter.byTenantAndCode(TenantReference.of("$ref"), "one");
    Assertions.assertEquals(TenantReference.of("$ref"), filter.getTenant().orElse(null),
        "Tenant must be the one of the unique index");
    Assertions.assertEquals("one", filter.getCode().orElse(null),
        "Code must be the one of the unique index");
  }
}
